<style>.qrhero{padding:24px;border-radius:22px;color:#fff;background:linear-gradient(135deg,#102a56,#7457e8,#10bfa3)}.qrcard{margin-top:20px;padding:20px;border-radius:20px;background:#fff}.qrcamera{position:relative;overflow:hidden;min-height:440px;border-radius:20px;background:#07172e}.qrcamera video{width:100%;height:440px;object-fit:cover}.qrframe{position:absolute;left:50%;top:50%;width:250px;height:250px;transform:translate(-50%,-50%);border:4px solid #ffd166;border-radius:28px;box-shadow:0 0 0 999px rgba(0,0,0,.42)}.qrstatus{padding:14px;margin-top:14px;border-radius:12px;background:#eef3fb;font-weight:700}.qrstatus.ok{background:#dcf8ef;color:#087f68}.qrstatus.bad{background:#ffe6e6;color:#b52222}</style>
<div class="qrhero"><h2><i class="fas fa-qrcode"></i> SchoolEdge QR Attendance</h2><p>Secure rotating passes with school and class authorization.</p></div>
<?php if(is_superadmin_loggedin()): ?><div class="qrcard"><label>School branch</label><?=form_dropdown('branch_id',$this->app_lib->getSelectList('branch'),$branch_id,'id="branchID" class="form-control" onchange="location.href=\''.base_url('schooledge_qr_attendance?branch_id=').'\'+this.value"')?></div><?php endif; ?>
<div class="qrcard"><div class="qrcamera"><video id="qrVideo" playsinline muted></video><div class="qrframe"></div></div><p class="mt-md"><button id="startQr" class="btn btn-primary"><i class="fas fa-camera"></i> Start camera</button> <button id="stopQr" class="btn btn-default">Stop</button></p><div class="input-group"><input id="qrToken" class="form-control" placeholder="Paste QR token"><span class="input-group-btn"><button id="sendQr" class="btn btn-default">Submit</button></span></div><div id="qrStatus" class="qrstatus">Ready to scan.</div></div>
<script>(function(){let stream,loop,busy=false;const v=document.getElementById('qrVideo'),s=document.getElementById('qrStatus');function msg(x,c){s.textContent=x;s.className='qrstatus '+(c||'')}async function send(token){if(busy||!token)return;busy=true;msg('Verifying pass…');const b=new URLSearchParams({token:token,branch_id:'<?=intval($branch_id)?>','<?=$this->security->get_csrf_token_name()?>':'<?=$this->security->get_csrf_hash()?>'});try{const r=await fetch('<?=base_url('schooledge_qr_attendance/scan')?>',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded'},body:b});const j=await r.json();if(!r.ok||!j.success)throw Error(j.error||'Scan failed');msg((j.data.already_marked?'Already marked: ':'Attendance recorded: ')+j.data.student.name,'ok')}catch(e){msg(e.message,'bad')}setTimeout(()=>busy=false,1800)}async function start(){if(!window.BarcodeDetector)return msg('Use current Chrome or Edge, or paste the token below.','bad');try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});v.srcObject=stream;await v.play();const d=new BarcodeDetector({formats:['qr_code']});msg('Scanning…');const tick=async()=>{if(!stream)return;try{const c=await d.detect(v);if(c.length)send(c[0].rawValue)}catch(e){}loop=requestAnimationFrame(tick)};tick()}catch(e){msg('Camera permission denied or unavailable.','bad')}}function stop(){if(loop)cancelAnimationFrame(loop);if(stream)stream.getTracks().forEach(x=>x.stop());stream=null;msg('Camera stopped.')}document.getElementById('startQr').onclick=start;document.getElementById('stopQr').onclick=stop;document.getElementById('sendQr').onclick=()=>send(document.getElementById('qrToken').value.trim());window.addEventListener('beforeunload',stop)})();</script>
